use std::io;

fn cross_product(o: &(i64, i64), a: &(i64, i64), b: &(i64, i64)) -> i64 {
    (a.0 - o.0) as i64 * (b.1 - o.1) as i64 - (b.0 - o.0) as i64 * (a.1 - o.1) as i64
}

fn main() {
    let mut input = String::new();
    io::stdin().read_line(&mut input).unwrap();
    let n = input.trim().parse::<usize>().unwrap();

    let mut a = Vec::new();
    for _ in 0..n {
        input = String::new();
        io::stdin().read_line(&mut input).unwrap();
        let coords: Vec<i64> = input.trim().split_whitespace()
            .map(|x| x.parse().unwrap())
            .collect();
        a.push((coords[0], coords[1]));
    }

    input = String::new();
    io::stdin().read_line(&mut input).unwrap();
    let m = input.trim().parse::<usize>().unwrap();

    let mut b = Vec::new();
    for _ in 0..m {
        input = String::new();
        io::stdin().read_line(&mut input).unwrap();
        let coords: Vec<i64> = input.trim().split_whitespace()
            .map(|x| x.parse().unwrap())
            .collect();
        b.push((coords[0], coords[1]));
    }

    // Since A is strictly convex and vertices are clockwise,
    // a point P is strictly inside A if cross_product(a[i], a[i+1], P) > 0 for all i.
    for &(px, py) in &b {
        for i in 0..a.len() {
            let p1 = a[i];
            let p2 = a[(i + 1) % a.len()];
            if cross_product(&p1, &p2, &(px, py)) <= 0 {
                println!("NO");
                return;
            }
        }
    }

    println!("YES");
}
